#---------------------------#
# DEBUG AREA 1N (TUNDRA)
@token    = debug-area-1n
@name     = DEBUG Area 1N
@level    = 20
@size     = 15 x 15
@sheet    = mmrpg-overworld-2k25
#---------------------------#
@portals[]  = spawn(8-12, hidden)
@portals[]  = goto__debug-area-1(8-12, 6-8)
@portals[]  = goto__debug-area-1n2(8-4, 25-13)
#---------------------------#
@field        = wintry-forefront
#---------------------------#
@pickups      = speed-pellet(6),energy-pellet(4),speed-capsule(2)
#---------------------------#
@encounters   = curlinger,frosty-throwman,tel-tel
#---------------------------#
@bosses[]     = south-spawn-boss(8-13, ice-man)
@bosses[]     = north-west-boss(4-4, blizzard-man)
@bosses[]     = north-east-boss(12-4, frost-man)
#---------------------------#
@events[]    = cossack-platform-left(7-2, cossackpad-left, any, drop-zone, item:cossack-program, activate-player-platform)
@events[]    = cossack-platform-middle(8-2, cossackpad-middle, any, drop-zone, item:cossack-heart, activate-player-platform)
@events[]    = cossack-platform-right(9-2, cossackpad-right, any, drop-zone, item:copy-core, activate-player-platform)
#---------------------------#
@items[]     = cossack-init-heart(4-3, cossack-heart__2, anchored)
@items[]     = cossack-init-program(12-3, cossack-program, anchored)
@items[]     = cossack-init-core(3-9, copy-core, anchored)
